// async-demo.js —— Node.js 异步编程：从 Promise 到 async/await
// 运行方式：node async-demo.js

const fs = require('node:fs/promises');
const path = require('node:path');

// ---------- 1. 用 Promise 模拟一个耗时的异步任务（比如查数据库） ----------
function delay(ms, value) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(value), ms);
  });
}

// ---------- 2. 用 async/await 顺序书写异步逻辑 ----------
async function serialDemo() {
  console.log('① 开始执行');

  const a = await delay(300, 10); // 等 300ms 后拿到 10
  console.log('② 拿到第一个值：', a);

  const b = await delay(200, 32); // 再等 200ms 后拿到 32
  console.log('③ 拿到第二个值：', b);

  console.log('④ 串行结果 =', a + b, '（总耗时约 500ms）');
}

// ---------- 3. 并发执行：Promise.all 同时等待多个任务 ----------
async function parallelDemo() {
  const start = Date.now();
  // 三个任务同时发起，总耗时约等于最慢的那个（300ms）
  const [x, y, z] = await Promise.all([
    delay(300, 'x'),
    delay(100, 'y'),
    delay(200, 'z'),
  ]);
  console.log('⑤ 并发结果：', x + y + z,
    '，耗时约', Date.now() - start, 'ms');
}

// ---------- 4. 真实的异步文件读写 ----------
async function fileDemo() {
  const file = path.join(__dirname, 'demo-output.txt');

  await fs.writeFile(file, 'hello async/await\n'); // 异步写
  const content = await fs.readFile(file, 'utf8');  // 异步读
  console.log('⑥ 文件内容：', content.trim());

  await fs.unlink(file); // 清理临时文件
}

// ---------- 5. 统一的错误处理入口 ----------
async function main() {
  await serialDemo();
  await parallelDemo();
  await fileDemo();

  // 演示错误处理：await 会把 Promise 的失败「抛」成同步异常
  try {
    await Promise.reject(new Error('模拟接口超时'));
  } catch (err) {
    console.log('⑦ 捕获到异步错误：', err.message);
  }
}

// 兜底：任何未被 try/catch 捕获的错误都会走到这里，避免进程静默崩溃
main().catch((err) => {
  console.error('程序出错：', err);
  process.exitCode = 1;
});

